"use client";

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { readMs } from "./motion";
import "./toasts.css";

export type Toast = { id: number; text: string; tone: "ok" | "error"; state: "live" | "dismiss" | "push" };

/* Banner stacking: a new toast rises in front, older ones step back, a fourth pushes the oldest out. */
export function useToasts() {
  const [list, setList] = useState<Toast[]>([]);
  const next = useRef(0);
  const timers = useRef(new Set<number>());

  const later = useCallback((fn: () => void, ms: number) => {
    const t = window.setTimeout(() => {
      timers.current.delete(t);
      fn();
    }, ms);
    timers.current.add(t);
  }, []);

  const drop = useCallback(
    (id: number, how: "dismiss" | "push") => {
      setList((cur) => cur.map((t) => (t.id === id && t.state === "live" ? { ...t, state: how } : t)));
      later(() => setList((cur) => cur.filter((t) => t.id !== id)), readMs("--stack-close", 250) + 60);
    },
    [later]
  );

  const toast = useCallback(
    (text: string, tone: "ok" | "error" = "ok") => {
      const id = ++next.current;
      setList((cur) => {
        const live = cur.filter((t) => t.state === "live");
        const out = new Set(live.slice(2).map((t) => t.id));
        if (out.size) later(() => setList((c) => c.filter((t) => !out.has(t.id))), readMs("--stack-close", 250) + 60);
        return [{ id, text, tone, state: "live" as const }, ...cur.map((t) => (out.has(t.id) ? { ...t, state: "push" as const } : t))];
      });
      later(() => drop(id, "dismiss"), tone === "error" ? 6000 : 2800);
    },
    [drop, later]
  );

  useEffect(() => {
    const all = timers.current;
    return () => all.forEach((t) => window.clearTimeout(t));
  }, []);

  return { list, toast, dismiss: (id: number) => drop(id, "dismiss") };
}

export function Toasts({ list, dismiss }: { list: Toast[]; dismiss: (id: number) => void }) {
  const live = list.filter((t) => t.state === "live");
  return (
    <div className="ob-toasts" aria-live="polite">
      <div className="t-stack">
        {list.map((t) => (
          <ToastBanner key={t.id} t={t} depth={Math.max(0, live.indexOf(t))} onTap={() => dismiss(t.id)} />
        ))}
      </div>
    </div>
  );
}

function ToastBanner({ t, depth, onTap }: { t: Toast; depth: number; onTap: () => void }) {
  const ref = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const el = ref.current!;
    el.classList.add("is-enter");
    void el.offsetWidth;
    el.classList.remove("is-enter");
  }, []);
  return (
    <div
      ref={ref}
      className={
        "t-stack-banner ob-toast" +
        (t.tone === "error" ? " is-error" : "") +
        (t.state === "push" ? " is-leaving" : t.state === "dismiss" ? " is-dismiss" : "")
      }
      data-depth={t.state === "live" ? depth : undefined}
      role={t.tone === "error" ? "alert" : "status"}
      onClick={onTap}
    >
      <span className="ob-toast-dot" aria-hidden="true">
        {t.tone === "error" ? (
          <svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
            <path d="M6 3v3.5M6 9h.01" />
          </svg>
        ) : (
          <svg width="12" height="12" viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <path d="M2.5 6.3l2.2 2.2L9.5 3.7" />
          </svg>
        )}
      </span>
      <span className="ob-toast-text">{t.text}</span>
    </div>
  );
}

/* Toasts: transitions.dev's banner stacking, dark pill on a light page and
   the other way round. Sits above a bottom dock; move it with
   --ob-toasts-bottom. */

.ob-toasts {
  position: fixed; left: 16px; right: 16px; z-index: 60;
  bottom: var(--ob-toasts-bottom, calc(env(safe-area-inset-bottom) + 96px));
  display: flex; justify-content: center; pointer-events: none;
}
.ob-toasts .t-stack { width: 100%; max-width: 400px; }
.ob-toast {
  right: 0; display: flex; align-items: center; gap: 10px;
  padding: 12px 16px 12px 12px; border-radius: 18px;
  background: var(--ds-color-text); color: var(--ds-color-bg);
  box-shadow: var(--ob-shadow-float, var(--ds-shadow-lg));
  font-weight: 600; font-size: 14.5px; pointer-events: auto; cursor: pointer;
}
.ob-toast-dot { width: 24px; height: 24px; border-radius: 50%; background: var(--ds-color-success); color: #fff; display: grid; place-items: center; flex: none; }
.ob-toast.is-error .ob-toast-dot { background: var(--ds-color-danger); }
.ob-toast-text { min-width: 0; }

/* Dismissal mirrors the entrance instead of stepping back into the stack. */
.t-stack-banner.is-dismiss {
  transform: translateY(var(--stack-rise)) scale(var(--stack-scale));
  opacity: 0;
  filter: blur(var(--stack-blur));
  transition: transform var(--stack-close) var(--stack-ease), opacity var(--stack-close) var(--stack-ease), filter var(--stack-close) var(--stack-ease);
}
